from pathlib import Path
import json
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
def one(rel):
    p=base/rel
    if not p.is_file():
        return {"exists":False}
    try:
        o=json.loads(p.read_text(encoding="utf-8"))
    except Exception as e:
        return {"exists":True,"read_error":type(e).__name__}
    if not isinstance(o,dict):
        return {"exists":True,"type":type(o).__name__}
    return {
      "exists":True,
      "task_id":o.get("task_id"),
      "state":o.get("state"),
      "reason":o.get("reason"),
      "attempt":o.get("attempt"),
      "checkpoint":o.get("checkpoint"),
      "next_action":o.get("next_action"),
      "retry_at":o.get("retry_at")
    }
out={
 "STATE":one("models/STATE.json"),
 "CONTINUATION":one("models/CONTINUATION.json"),
 "BLOCKER":one("models/BLOCKER.json"),
 "result_exists":(base/"model_results"/(task+".json")).is_file()
}
print("ERROR_CLASS=R4P2_STATE_MINIMAL",flush=True)
print("ERROR="+json.dumps(out,separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(1)
